import{_ as a,m as t,n as i,q as s}from"./chunks/framework.DMDh-7Lg.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),r={name:"faq.md"};function o(l,e,n,h,d,u){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="is-klix-command-first-or-chat-first" tabindex="-1">Is Klix command-first or chat-first? <a class="header-anchor" href="#is-klix-command-first-or-chat-first" aria-label="Permalink to &quot;Is Klix command-first or chat-first?&quot;">​</a></h2><p>Command-first by default.</p><p>The built-in <code>App.run()</code> loop is built around slash commands. You can build chat-style flows on top of the same primitives, but that usually means writing a custom loop like <code>examples/chat_ai.py</code>.</p><p>See <a href="./examples/gemini-style-cli">Examples: Gemini-Style CLI</a>.</p><h2 id="why-does-the-router-not-support-shell-style-quoting" tabindex="-1">Why does the router not support shell-style quoting? <a class="header-anchor" href="#why-does-the-router-not-support-shell-style-quoting" aria-label="Permalink to &quot;Why does the router not support shell-style quoting?&quot;">​</a></h2><p>Because the current parser is intentionally simple. It splits on whitespace and hands typed validation to Pydantic. That keeps the routing layer small and predictable, but it also means quoted strings with spaces are not treated specially.</p><p>See <a href="./concepts/router">Router</a>.</p><h2 id="does-klix-support-subcommands" tabindex="-1">Does Klix support subcommands? <a class="header-anchor" href="#does-klix-support-subcommands" aria-label="Permalink to &quot;Does Klix support subcommands?&quot;">​</a></h2><p>Not as a first-class nested command tree.</p><p>The common pattern is to model subcommand-like behavior inside a single command’s argument schema or handler logic.</p><p>See <a href="./guides/adding-commands">Adding Commands</a>.</p><h2 id="why-is-there-both-middleware-and-events" tabindex="-1">Why is there both middleware and events? <a class="header-anchor" href="#why-is-there-both-middleware-and-events" aria-label="Permalink to &quot;Why is there both middleware and events?&quot;">​</a></h2><p>They solve different problems.</p><ul><li>middleware wraps command execution</li><li>events observe lifecycle moments</li></ul><p>If you need before/after behavior around a handler, use middleware. If you need startup, shutdown, or error hooks, use events.</p><p>See <a href="./concepts/middleware">Middleware</a> and <a href="./concepts/events">Events</a>.</p><h2 id="does-klix-persist-sessions-automatically" tabindex="-1">Does Klix persist sessions automatically? <a class="header-anchor" href="#does-klix-persist-sessions-automatically" aria-label="Permalink to &quot;Does Klix persist sessions automatically?&quot;">​</a></h2><p>It can save state automatically when <code>persist_session=True</code>, but loading a prior session still requires a session identifier or custom resume logic. Save-on-exit and resume-on-start are related, but they are not the same feature.</p><p>See <a href="./guides/persistence">Persistence</a>.</p><h2 id="can-i-build-a-full-screen-tui-with-klix" tabindex="-1">Can I build a full-screen TUI with Klix? <a class="header-anchor" href="#can-i-build-a-full-screen-tui-with-klix" aria-label="Permalink to &quot;Can I build a full-screen TUI with Klix?&quot;">​</a></h2><p>You can build polished terminal apps with headers, status lines, widgets, and interactive prompts, but Klix is not a full retained-mode TUI framework. The layout system is intentionally coarse and works best for lightweight structure.</p><p>See <a href="./concepts/layout">Layout</a>.</p><h2 id="why-is-there-no-default-help" tabindex="-1">Why is there no default <code>--help</code>? <a class="header-anchor" href="#why-is-there-no-default-help" aria-label="Permalink to &quot;Why is there no default `--help`?&quot;">​</a></h2><p>The process-level parser is created with <code>add_help=False</code>. The current design expects command help to be handled at the app level, usually through a <code>/help</code> command and the built-in help generator.</p><p>See <a href="./reference/config">Reference: Config</a>.</p><h2 id="are-rich-widgets-required" tabindex="-1">Are rich widgets required? <a class="header-anchor" href="#are-rich-widgets-required" aria-label="Permalink to &quot;Are rich widgets required?&quot;">​</a></h2><p>No.</p><p>Klix prefers rich when the terminal supports it, but it ships fallback and CI renderers so apps still run in simpler environments. The visual result is reduced, but the app should remain usable.</p><p>See <a href="./concepts/renderer">Renderer</a>.</p><h2 id="what-should-i-put-in-session-state" tabindex="-1">What should I put in <code>session.state</code>? <a class="header-anchor" href="#what-should-i-put-in-session-state" aria-label="Permalink to &quot;What should I put in `session.state`?&quot;">​</a></h2><p>Put typed, session-scoped, serializable application state there:</p><ul><li>selected profile</li><li>recent actions</li><li>user preferences</li><li>in-progress workflow data</li></ul><p>Do not put renderer objects, prompt sessions, or random global caches there.</p><p>See <a href="./guides/working-with-state">Working With State</a>.</p><h2 id="how-should-i-think-about-session-ui" tabindex="-1">How should I think about <code>session.ui</code>? <a class="header-anchor" href="#how-should-i-think-about-session-ui" aria-label="Permalink to &quot;How should I think about `session.ui`?&quot;">​</a></h2><p>As the main application-facing terminal API.</p><p>It is the place where input, output, layout, and streaming come together. Most app code should work through <code>session.ui</code> rather than importing lower-level renderer or input pieces directly.</p><p>See <a href="./concepts/ui">UI</a>.</p><h2 id="what-are-the-biggest-current-limitations" tabindex="-1">What are the biggest current limitations? <a class="header-anchor" href="#what-are-the-biggest-current-limitations" aria-label="Permalink to &quot;What are the biggest current limitations?&quot;">​</a></h2><p>The main ones are:</p><ul><li>command parsing is intentionally simple</li><li>layout is lightweight, not full retained-mode UI</li><li>persistence is basic and session-file oriented</li><li>autocomplete is helpful but not schema-driven</li></ul><p>These are tradeoffs, not accidents. Klix is trying to stay small and practical.</p><h2 id="what-should-i-read-first-if-i-am-new" tabindex="-1">What should I read first if I am new? <a class="header-anchor" href="#what-should-i-read-first-if-i-am-new" aria-label="Permalink to &quot;What should I read first if I am new?&quot;">​</a></h2><p>This order works well:</p><ol><li><a href="./">Index</a></li><li><a href="./installation">Installation</a></li><li><a href="./quickstart">Quickstart</a></li><li><a href="./concepts/architecture">Architecture</a></li><li><a href="./guides/building-your-first-cli">Building Your First CLI</a></li></ol>',46)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
